(function(){window.KOREANITA_ASSETS=window.KOREANITA_ASSETS||{};window.KOREANITA_ASSETS.halloweenPromo='data:image/webp;base64,';function setPromo(){var img=document.getElementById('halloweenPromo'); if(img && !img.src) img.src=window.KOREANITA_ASSETS.halloweenPromo;}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',setPromo);}else{setPromo();}})();